args.command:
export HOME=/tmp/probe_base; cd $HOME; export XDG_CONFIG_HOME=$HOME/.config PIER_CONFIG_PATH=$HOME/cfg.toml
v=$(printf 'echo x\n\n'; echo .); v=${v%.}
/workspace/executable add -f -a trailnl "$v" >out.txt 2>err.txt; echo "exit=$?"; cat -A out.txt; cat -A err.txt
v2=$(printf '\necho y'; echo .); v2=${v2%.}
/workspace/executable add -a leadnl "$v2" >out.txt 2>err.txt; echo "exit=$?"; cat -A out.txt; cat -A err.txt
grep -n -A6 'scripts.trailnl\]\|scripts.leadnl\]' cfg.toml | cat -A
